messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Three.js Humanoid Cycle</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #111; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // --- Setup Scene ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x222222);
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
    scene.add(ambientLight);
    const dirLight = new THREE.DirectionalLight(0xffffff, 1);
    dirLight.position.set(5, 10, 5);
    dirLight.castShadow = true;
    scene.add(dirLight);

    // --- Treadmill Ground ---
    const groundGeo = new THREE.BoxGeometry(4, 0.2, 10);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x444444 });
    const ground = new THREE.Mesh(groundGeo);
    ground.receiveShadow = true;
    scene.add(ground);

    // Treadmill texture effect (moving lines)
    const grid = new THREE.GridHelper(10, 20, 0x888888, 0x333333);
    grid.position.y = 0.11;
    scene.add(grid);

    // --- Humanoid Construction ---
    const bodyGroup = new THREE.Group();
    scene.add(bodyGroup);

    const mat = new THREE.MeshStandardMaterial({ color: 0x00ffcc });
    const skinMat = new THREE.MeshStandardMaterial({ color: 0xffccaa });

    // Torso
    const torso = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.8, 0.3), mat);
    torso.position.y = 1.4;
    torso.castShadow = true;
    bodyGroup.add(torso);

    // Head
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.3, 0.3), skinMat);
    head.position.y = 0.6;
    torso.add(head);

    // Helper to create limbs
    function createLimb(w, h, d, color) {
        const group = new THREE.Group();
        const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), color);
        mesh.position.y = -h / 2; // pivot from top
        mesh.castShadow = true;
        group.add(mesh);
        return group;
    }

    const leftArm = createLimb(0.15, 0.6, 0.15, mat);
    leftArm.position.set(0.4, 0.7, 0);
    torso.add(leftArm);

    const rightArm = createLimb(0.15, 0.6, 0.15, mat);
    rightArm.position.set(-0.4, 0.7, 0);
    torso.add(rightArm);

    const leftLeg = createLimb(0.2, 0.7, 0.2, mat);
    leftLeg.position.set(0.2, -0.4, 0);
    torso.add(leftLeg);

    const rightLeg = createLimb(0.2, 0.7, 0.2, mat);
    rightLeg.position.set(-0.2, -0.4, 0);
    torso.add(rightLeg);

    // --- Camera Position ---
    camera.position.set(4, 2.5, 4);
    camera.lookAt(0, 1, 0);

    // --- Animation Logic ---
    const clock = new THREE.Clock();

    function animate() {
        requestAnimationFrame(animate);
        const elapsed = clock.getElapsedTime() % 10; // 10s loop
        const t = clock.getElapsedTime();

        // Reset poses
        torso.rotation.x = 0;
        torso.rotation.z = 0;
        leftArm.rotation.x = 0;
        rightArm.rotation.x = 0;
        leftLeg.rotation.x = 0;
        rightLeg.rotation.x = 0;

        // Treadmill visual movement
        grid.position.z = (t * 3) % 1;

        // State Machine
        // 0-2s: Still
        // 2-5s: Walk (3s)
        // 5-8s: Run (3s)
        // 8-10s: Still (2s)

        if (elapsed < 2 || elapsed > 8) {
            // STAND STILL
            // No movement
        } 
        else if (elapsed >= 2 && elapsed < 5) {
            // WALK
            const walkTime = elapsed - 2;
            const speed = 6;
            const amplitude = 0.5;

            // Limb swing
            leftArm.rotation.x = Math.sin(walkTime * speed) * amplitude;
            rightArm.rotation.x = -Math.sin(walkTime * speed) * amplitude;
            leftLeg.rotation.x = -Math.sin(walkTime * speed) * amplitude;
            rightLeg.rotation.x = Math.sin(walkTime * speed) * amplitude;

            // Slight vertical bobbing
            bodyGroup.position.y = Math.abs(Math.cos(walkTime * speed * 2)) * 0.05;
        } 
        else if (elapsed >= 5 && elapsed < 8) {
            // RUN
            const runTime = elapsed - 5;
            const speed = 12;
            const amplitude = 0.8;

            // Faster, larger swings
            leftArm.rotation.x = Math.sin(runTime * speed) * amplitude;
            rightArm.rotation.x = -Math.sin(runTime * speed) * amplitude;
            leftLeg.rotation.x = -Math.sin(runTime * speed) * amplitude;
            rightLeg.rotation.x = Math.sin(runTime * speed) * amplitude;

            // Forward lean
            torso.rotation.x = 0.3; 

            // Higher vertical bobbing
            bodyGroup.position.y = Math.abs(Math.cos(runTime * speed * 2)) * 0.15;
        }

        renderer.render(scene, camera);
    }

    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    animate();
</script>
</body>
</html>
```
